package com.enis.sectio.task; import java.time.Instant;
public record TaskResponse(Long id,Long projectId,String projectName,Long createdById,String createdByName,Long assigneeId,String assigneeName,String title,String description,TaskStatus status,TaskPriority priority,Instant dueAt,Instant completedAt,Instant createdAt,Instant updatedAt){public static TaskResponse from(Task t){var a=t.getAssignee();return new TaskResponse(t.getId(),t.getProject().getId(),t.getProject().getName(),t.getCreatedBy().getId(),t.getCreatedBy().getName(),a==null?null:a.getId(),a==null?null:a.getName(),t.getTitle(),t.getDescription(),t.getStatus(),t.getPriority(),t.getDueAt(),t.getCompletedAt(),t.getCreatedAt(),t.getUpdatedAt());}}
